import sys

def solve():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    n = int(input_data[0])
    p = []
    for i in range(n):
        p.append(int(input_data[i + 1]))

    s = input_data[n + 1]

    # Calculate base score for Bob (without any flip)
    # Base score is sum of p[i] where s[i] == 'B'
    current_bob_score = 0
    for i in range(n):
        if s[i] == 'B':
            current_bob_score += p[i]

    max_score = current_bob_score

    # Calculate gain for flipping prefixes
    # Gain = sum(p[i] for i in range(k) if s[i]=='B') - sum(p[i] for i in range(k) if s[i]=='A')
    # Which is equivalent to: sum over i in [0, k-1] of (p[i] if s[i]=='B' else -p[i])

    # Prefix gains
    current_gain = 0
    for i in range(n):
        if s == 'B':
            current_gain += p[i]
        else:
            current_gain -= p[i]

        if current_gain > 0:
            if current_bob_score + current_gain > max_score:
                max_score = current_bob_score + current_gain

    # Suffix gains
    current_gain = 0
    for i in range(n - 1, -1, -1):
        if s[i] == 'B':
            current_gain += p[i]
        else
            current_gain -= p[i]

        if current_gain > max_score:
            if current_bob_score + current_gain > max_score: max_score = current_bob_score + current_gain

    print(max_score)

solve()
